function saveSVG(fileName = "epi.svg.txt") {
	// generate svg output
	const svgGrps = [];
	for (let i = 0; i < CLRS.length; i++) {
		svgGrps[i] = "";
	}

	for (let j = 0; j < svgGrArr.length; j++) {
		const vtxPoints = svgGrArr[j];
		// console.log(vtxPoints);

		for (let circs of vtxPoints) {
			let svgLine = `<polyline points="`;
			for (let pt of circs) {
				// console.log(pt)
				svgLine += `${nf(pt.x,0,2)} ${nf(pt.y,0,2)} `;
			}
			svgLine += `" />\n`;
			svgGrps[j%CLRS.length] += svgLine;
		}
	}  

	let svgStr = `<svg width="${width}" height="${width}" version="1.1" xmlns="http://www.w3.org/2000/svg">\n`;
	for (let i = 0; i < svgGrps.length; i++) {
		svgStr += `<g stroke="${CLRS[i]}" fill="none" stroke-width="1">\n${svgGrps[i]}\n</g>\n`;
	}
	svgStr += `</svg>`;

	save(svgStr.split("\n"), fileName)

}

